package de.unihamburg.daibetes.api.project.training.federated;

import bio.cosy.feddb.core.base.BaseEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import lombok.Getter;
import lombok.Setter;

/**
 * A single row: the platform's own Flower SuperLink CA, as generated by the aggregator attempt of
 * the platform's first Flower run (or the run that renewed it before expiry). This is the CA's
 * only lasting home - the aggregator's container and its files are gone after every run. Each run
 * hands the certificate to its clinics (FederatedTrainingSetupBO#flowerClinicSlots) and the
 * certificate and key to its own aggregator (FederatedTrainingFlowerAggregatorBO#customizeStartup),
 * which signs that run's SuperLink leaf certificate with it, so the CA clinics trust is always the
 * one the SuperLink presents. Stable across runs, unlike relay credentials, which are per-run.
 */
@Setter
@Getter
@Entity
@Table(name = "flower_platform_certificate")
public class FlowerPlatformCertificateEntity extends BaseEntity {

    @Column(name = "ca_certificate", columnDefinition = "TEXT", nullable = false)
    private String caCertificate;

    // Sent only to the platform's own aggregator attempt, never to a clinic.
    @Column(name = "ca_private_key", columnDefinition = "TEXT", nullable = false)
    private String caPrivateKey;
}
